{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-69wKX0/src/address.js","content":"/**
 * Cell address parsing and formatting. An address is one or two letters
 * naming a column (A..Z, then AA..ZZ) followed by one to three digits
 * naming a row of at least 1.
 */

/** Converts uppercase column letters ("A".."ZZ") to a 1-based column index. */
export function colLettersToIndex(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/** Converts a 1-based column index back to uppercase column letters. */
export function colIndexToLetters(index) {
  let n = index
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parses a raw word as an address. Returns { valid:false } when the word
 * is not letters followed by digits, has the wrong letter/digit counts, or
 * names a row below 1 -- all of which are "outside the addressable range"
 * rather than a parse failure. On success returns the column index, row
 * number, and the canonical "A1"-style spelling.
 */
export function parseAddressWord(raw) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(raw)
  if (!m) return { valid: false }
  const [, letters, digits] = m
  if (letters.length < 1 || letters.length > 2) return { valid: false }
  if (digits.length < 1 || digits.length > 3) return { valid: false }
  const row = parseInt(digits, 10)
  if (row < 1) return { valid: false }
  const col = colLettersToIndex(letters.toUpperCase())
  return { valid: true, col, row, canonical: colIndexToLetters(col) + row }
}

/** Builds the canonical "A1"-style address for a column index and row. */
export function canonicalAddress(col, row) {
  return colIndexToLetters(col) + row
}

/** Compares two canonical addresses by column then row, ascending. */
export function compareAddresses(a, b) {
  const infoA = parseAddressWord(a)
  const infoB = parseAddressWord(b)
  if (infoA.col !== infoB.col) return infoA.col - infoB.col
  return infoA.row - infoB.row
}

/**
 * Expands a range between two corner addresses into every covered cell, in
 * ascending column order and, within a column, ascending row order,
 * regardless of which corner the range was written from.
 */
export function expandRange(startInfo, endInfo) {
  const colMin = Math.min(startInfo.col, endInfo.col)
  const colMax = Math.max(startInfo.col, endInfo.col)
  const rowMin = Math.min(startInfo.row, endInfo.row)
  const rowMax = Math.max(startInfo.row, endInfo.row)
  const cells = []
  for (let c = colMin; c <= colMax; c++) {
    for (let r = rowMin; r <= rowMax; r++) {
      cells.push(canonicalAddress(c, r))
    }
  }
  return cells
}
"}

