{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-69wKX0/src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`). Spaces and
 * tabs separate tokens and are otherwise insignificant.
 */

const NUMBER_RE = /[0-9]+(\.[0-9]+)?/y
const IDENT_RE = /[A-Za-z]+[0-9]*/y

/**
 * Splits a formula body into tokens. Returns { ok:false } for any
 * character the grammar does not know, which makes the whole formula a
 * grammar failure.
 */
export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      NUMBER_RE.lastIndex = i
      const m = NUMBER_RE.exec(src)
      tokens.push({ type: 'NUM', value: parseFloat(m[0]) })
      i = NUMBER_RE.lastIndex
      continue
    }
    if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) {
      IDENT_RE.lastIndex = i
      const m = IDENT_RE.exec(src)
      tokens.push({ type: 'IDENT', value: m[0] })
      i = IDENT_RE.lastIndex
      continue
    }
    if (ch === '<') {
      if (src[i + 1] === '=') { tokens.push({ type: 'OP', value: '<=' }); i += 2; continue }
      if (src[i + 1] === '>') { tokens.push({ type: 'OP', value: '<>' }); i += 2; continue }
      tokens.push({ type: 'OP', value: '<' }); i += 1; continue
    }
    if (ch === '>') {
      if (src[i + 1] === '=') { tokens.push({ type: 'OP', value: '>=' }); i += 2; continue }
      tokens.push({ type: 'OP', value: '>' }); i += 1; continue
    }
    if (ch === '=') { tokens.push({ type: 'OP', value: '=' }); i += 1; continue }
    if (ch === '^' || ch === '*' || ch === '/' || ch === '+' || ch === '-') {
      tokens.push({ type: 'OP', value: ch }); i += 1; continue
    }
    if (ch === '(') { tokens.push({ type: 'LP' }); i += 1; continue }
    if (ch === ')') { tokens.push({ type: 'RP' }); i += 1; continue }
    if (ch === ',') { tokens.push({ type: 'COMMA' }); i += 1; continue }
    if (ch === ':') { tokens.push({ type: 'COLON' }); i += 1; continue }
    return { ok: false }
  }
  tokens.push({ type: 'EOF' })
  return { ok: true, tokens }
}
"}

