      }
      return { type: 'Address', ...startInfo }
    }
    throw new ParseError('unexpected token')
  }

  parseArgs() {
    this.expect('LP')
    const args = []
    if (this.current().type === 'RP') {
      this.advance()
      return args
    }
    for (;;) {
      args.push(this.parseComparison())
      if (this.current().type === 'COMMA') {
        this.advance()
        continue
      }
      break
    }
    this.expect('RP')
    return args
  }
