export function parseFormula(body) {
  const lexed = tokenize(body)
  if (!lexed.ok) return { ok: false }
  try {
    const ast = new Parser(lexed.tokens).parseTop()
    return { ok: true, ast }
  } catch (e) {
    if (e instanceof ParseError) return { ok: false }
    throw e
  }
