 * function argument. Such a formula is grammar-accepted (so it is still
 * walked for dependencies) but always evaluates to `#ERR!`.
 */
export function findMisplacedRange(node) {
  return walk(node, false)

  function walk(n, isDirectArg) {
    switch (n.type) {
      case 'Range':
        return !isDirectArg
      case 'Number':
      case 'Bool':
      case 'Address':
        return false
      case 'UnaryOp':
        return walk(n.operand, false)
      case 'BinOp':
        return walk(n.left, false) || walk(n.right, false)
      case 'Call':
        return n.args.some((arg) => walk(arg, true))
      default:
        return false
    }
  }
}
