  if (a.t !== b.t) return Math.sign(KIND_RANK[a.t] - KIND_RANK[b.t])
  if (a.t === 'num') return Math.sign(a.v - b.v)
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  return Math.sign((a.v ? 1 : 0) - (b.v ? 1 : 0))
}

