 * The evaluation engine: turns declared cell content into values, with
 * memoization and cycle detection, and the parallel "which cells does this
 * formula name" walk used by `deps` mode.
 */
import { parseFormula, findMisplacedRange } from './parser.js'
import { parseAddressWord, expandRange } from './address.js'
import { numVal, textVal, boolVal, errVal, numResult, toNumberStrict, compareValues, isErrorLiteral } from './values.js'

const LITERAL_NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/

function parseLiteral(content) {
  if (content === '') return numVal(0)
  if (isErrorLiteral(content)) return errVal(content)
  if (LITERAL_NUMBER_RE.test(content)) return numVal(parseFloat(content))
  return textVal(content)
}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const ARG_COUNT_OK = {
  SUM: (n) => n >= 1,
  MIN: (n) => n >= 1,
  MAX: (n) => n >= 1,
  AVG: (n) => n >= 1,
  COUNT: (n) => n >= 1,
  ABS: (n) => n === 1,
  IF: (n) => n === 3,
}
const KNOWN_FUNCTIONS = new Set(Object.keys(ARG_COUNT_OK))

/** A sheet's declared cells (address -> raw content) plus a value/parse cache. */
export class Sheet {
  constructor(cells) {
    this.cells = cells // Map<address, content>
    this.formulaCache = new Map() // content -> parse result
    this.valueCache = new Map() // address -> value
    this.stack = [] // addresses currently being evaluated, for cycle detection
  }

  parsedFormula(content) {
    if (this.formulaCache.has(content)) return this.formulaCache.get(content)
    const body = content.slice(1)
    const parsed = parseFormula(body)
    const result = parsed.ok ? { ok: true, ast: parsed.ast, misplaced: findMisplacedRange(parsed.ast) } : { ok: false }
    this.formulaCache.set(content, result)
    return result
  }

  /** Evaluates a declared or undeclared cell, with cycle detection. */
  evalCell(address) {
    if (this.valueCache.has(address)) return this.valueCache.get(address)
    const idx = this.stack.indexOf(address)
    if (idx !== -1) {
      for (let i = idx; i < this.stack.length; i++) this.valueCache.set(this.stack[i], errVal('#CYCLE!'))
      throw { cycleOrigin: address }
    }
    this.stack.push(address)
    let result
    try {
      result = this.computeCell(address)
    } catch (e) {
      this.stack.pop()
      if (e && typeof e === 'object' && 'cycleOrigin' in e) {
        if (e.cycleOrigin === address) return this.valueCache.get(address)
        throw e
      }
      throw e
    }
    this.stack.pop()
    this.valueCache.set(address, result)
    return result
  }

  computeCell(address) {
    const content = this.cells.get(address) ?? ''
    if (!content.startsWith('=')) return parseLiteral(content)
    const formula = this.parsedFormula(content)
    if (!formula.ok || formula.misplaced) return errVal('#ERR!')
    return evaluate(formula.ast, this)
  }

  /** The addresses a declared cell's content names directly, ranges expanded. */
  depsFor(address) {
    const content = this.cells.get(address) ?? ''
    if (!content.startsWith('=')) return []
    const formula = this.parsedFormula(content)
    if (!formula.ok) return []
    const set = new Set()
    collectDeps(formula.ast, set)
    return [...set]
  }
}

function collectDeps(node, set) {
  switch (node.type) {
    case 'Address':
      if (node.valid) set.add(node.canonical)
      return
    case 'Range':
      if (node.start.valid && node.end.valid) {
        for (const addr of expandRange(node.start, node.end)) set.add(addr)
      }
      return
    case 'UnaryOp':
      collectDeps(node.operand, set)
      return
    case 'BinOp':
      collectDeps(node.left, set)
      collectDeps(node.right, set)
      return
    case 'Call':
      for (const arg of node.args) collectDeps(arg, set)
      return
    default:
      return
  }
}

function evaluate(node, sheet) {
  switch (node.type) {
    case 'Number':
      return numVal(node.value)
    case 'Bool':
      return boolVal(node.value)
    case 'Address':
      return node.valid ? sheet.evalCell(node.canonical) : errVal('#REF!')
    case 'Range':
      return evalRangeAsScalar(node, sheet)
    case 'UnaryOp':
      return evalUnary(node, sheet)
    case 'BinOp':
      return evalBinOp(node, sheet)
    case 'Call':
      return evalCall(node, sheet)
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

function evalRangeAsScalar(node, sheet) {
  if (!node.start.valid || !node.end.valid) return errVal('#REF!')
  const cells = expandRange(node.start, node.end)
  if (cells.length === 1) return sheet.evalCell(cells[0])
  return errVal('#VALUE!')
}

function evalUnary(node, sheet) {
  const operand = evaluate(node.operand, sheet)
  if (operand.t === 'err') return operand
  const n = toNumberStrict(operand)
  if (n.err) return n.err
  return numResult(node.op === '-' ? -n.n : n.n)
}

function evalBinOp(node, sheet) {
  const left = evaluate(node.left, sheet)
  const right = evaluate(node.right, sheet)
  if (left.t === 'err') return left
  if (right.t === 'err') return right
  if (COMPARISON_OPS.has(node.op)) return compareBin(node.op, left, right)
  const ln = toNumberStrict(left)
  if (ln.err) return ln.err
  const rn = toNumberStrict(right)
  if (rn.err) return rn.err
  switch (node.op) {
    case '+': return numResult(ln.n + rn.n)
    case '-': return numResult(ln.n - rn.n)
    case '*': return numResult(ln.n * rn.n)
    case '/': return numResult(ln.n / rn.n)
    case '^': return numResult(Math.pow(ln.n, rn.n))
    default: throw new Error(`unknown operator ${node.op}`)
  }
}

function compareBin(op, left, right) {
  const cmp = compareValues(left, right)
  switch (op) {
    case '=': return boolVal(cmp === 0)
    case '<>': return boolVal(cmp !== 0)
    case '<': return boolVal(cmp < 0)
    case '<=': return boolVal(cmp <= 0)
    case '>': return boolVal(cmp > 0)
    case '>=': return boolVal(cmp >= 0)
    default: throw new Error(`unknown comparator ${op}`)
  }
}

function evalCall(node, sheet) {
  const name = node.name.toUpperCase()
  if (!KNOWN_FUNCTIONS.has(name)) return errVal('#NAME?')
  if (!ARG_COUNT_OK[name](node.args.length)) return errVal('#ERR!')
  if (name === 'ABS') return evalAbs(node, sheet)
  if (name === 'IF') return evalIf(node, sheet)
  return evalAggregate(name, node.args, sheet)
}

function evalAbs(node, sheet) {
  const value = evaluate(node.args[0], sheet)
  if (value.t === 'err') return value
  const n = toNumberStrict(value)
  if (n.err) return n.err
  return numResult(Math.abs(n.n))
}

function evalIf(node, sheet) {
  const cond = evaluate(node.args[0], sheet)
  if (cond.t === 'err') return cond
  let truthy
  if (cond.t === 'bool') truthy = cond.v
  else if (cond.t === 'num') truthy = cond.v !== 0
  else return errVal('#VALUE!')
  return evaluate(node.args[truthy ? 1 : 2], sheet)
}

function evalAggregate(name, argNodes, sheet) {
  const values = []
  for (const argNode of argNodes) {
    if (argNode.type === 'Range') {
      if (!argNode.start.valid || !argNode.end.valid) {
        values.push(errVal('#REF!'))
        continue
      }
      for (const addr of expandRange(argNode.start, argNode.end)) values.push(sheet.evalCell(addr))
    } else {
      values.push(evaluate(argNode, sheet))
    }
  }
  if (name === 'COUNT') {
    for (const v of values) if (v.t === 'err') return v
    return numVal(values.filter((v) => v.t === 'num').length)
  }
  const nums = []
  for (const v of values) {
    if (v.t === 'err') return v
    const n = toNumberStrict(v)
    if (n.err) return n.err
    nums.push(n.n)
  }
  if (name === 'SUM') return numResult(nums.reduce((a, b) => a + b, 0))
  if (name === 'MIN') return numResult(Math.min(...nums))
  if (name === 'MAX') return numResult(Math.max(...nums))
  if (name === 'AVG') return numResult(nums.reduce((a, b) => a + b, 0) / nums.length)
  throw new Error(`unknown aggregate ${name}`)
}
"}

