  let i = 0
  while (i < trimmedLine.length && trimmedLine[i] !== ' ' && trimmedLine[i] !== '\t') i++
  const addr = trimmedLine.slice(0, i)
  let j = i
  while (j < trimmedLine.length && (trimmedLine[j] === ' ' || trimmedLine[j] === '\t')) j++
  const content = trimmedLine.slice(j)
  return { addr, content }
}

/** Parses sheet text into Map<canonical address, raw content>. */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].replace(/^[ \t]+/, '')
    if (trimmed === '' || trimmed[0] === '#') continue

    const { addr, content } = splitAddressAndContent(trimmed)
    const info = parseAddressWord(addr)
