/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import fs from 'node:fs'
import { parseSheet, SheetError } from './parse-sheet.js'
import { Sheet } from './evaluate.js'
import { formatValue } from './values.js'
import { compareAddresses } from './address.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('error: usage: cli.js values|deps')
  }
  const mode = argv[0]

  const input = fs.readFileSync(0, 'utf8')
  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const addresses = [...cells.keys()].sort(compareAddresses)
  const sheet = new Sheet(cells)
  const lines = []
  if (mode === 'values') {
    for (const addr of addresses) {
      const value = sheet.evalCell(addr)
      lines.push(`${addr}=${formatValue(value)}`)
    }
  } else {
    for (const addr of addresses) {
      const deps = sheet.depsFor(addr).sort(compareAddresses)
      lines.push(`${addr}:${deps.map((d) => ` ${d}`).join('')}`)
    }
  }
  process.stdout.write(lines.map((l) => l + '\n').join(''))
}

main()
"}

